package com.hrm.service;
import java.time.*;import java.util.*;import com.hrm.security.AuthenticatedAccount;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Service public class DepartmentReviewService {
 private final JdbcTemplate db;private final DepartmentWorkspaceAccess access;private final NotificationPublisher notices;
 public DepartmentReviewService(JdbcTemplate db,DepartmentWorkspaceAccess access,NotificationPublisher notices){this.db=db;this.access=access;this.notices=notices;}
 public static final String SOURCES="""
  (SELECT 'OT' kind,o.overtime_id id,o.employee_id,o.request_code code,o.requested_start starts,o.requested_end ends,o.reason,o.status sourceStatus,o.submitted_at submitted,
    CONVERT(varchar(64),HASHBYTES('SHA2_256',CONCAT(o.requested_start,'|',o.requested_end,'|',o.reason,'|',o.work_content,'|',(SELECT b.break_start,b.break_end FROM dbo.overtime_requested_breaks b WHERE b.overtime_id=o.overtime_id AND b.is_active=1 ORDER BY b.break_start,b.break_end FOR JSON PATH))),2) fingerprint FROM dbo.overtime_requests o
   UNION ALL SELECT 'ATTENDANCE',r.request_id,s.employee_id,r.request_code,COALESCE(r.proposed_start,s.planned_start),COALESCE(r.proposed_end,s.planned_end),r.reason,r.status,r.submitted_at,
    CONVERT(varchar(64),HASHBYTES('SHA2_256',CONCAT(r.proposed_start,'|',r.proposed_end,'|',r.proposed_break_minutes,'|',r.reason)),2) FROM dbo.attendance_portal_requests r JOIN dbo.work_schedules s ON s.schedule_id=r.schedule_id) source
  """;
 public Map<String,Object> source(String kind,long id){if(!Set.of("OT","ATTENDANCE").contains(kind)||id<=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Loại đơn không hợp lệ");var rows=db.queryForList("SELECT source.*,e.employee_code employeeCode,e.full_name fullName FROM "+SOURCES+" JOIN dbo.employees e ON e.employee_id=source.employee_id WHERE source.kind=? AND source.id=?",kind,id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy đơn");return rows.get(0);}
 public Map<String,Object> detail(AuthenticatedAccount p,String kind,long id){var row=source(kind,id);access.employee(p,((Number)row.get("employee_id")).longValue(),((java.sql.Timestamp)row.get("starts")).toLocalDateTime().toLocalDate(),false);row.put("history",db.queryForList("SELECT l.occurred_at occurredAt,l.action,l.reason,a.username actor FROM dbo.audit_logs l LEFT JOIN dbo.accounts a ON a.account_id=l.actor_account_id WHERE l.target_table='department_workflow_reviews' AND l.target_record_key=? ORDER BY l.audit_id DESC",kind+":"+id));row.put("review",db.queryForList("SELECT r.decision,r.reason,r.decided_at decidedAt,a.username reviewer FROM dbo.department_workflow_reviews r JOIN dbo.accounts a ON a.account_id=r.reviewer_id WHERE r.source_type=? AND r.source_id=? AND r.source_fingerprint=?",kind,id,row.get("fingerprint")));return row;}
 @Transactional("scheduleTransactionManager") public void decide(AuthenticatedAccount p,String kind,long id,boolean approve,String reason,String expectedVersion){
  if(reason==null||reason.isBlank()||reason.length()>1000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Nhập lý do duyệt/từ chối cấp phòng, tối đa 1000 ký tự");
  // Lock the business source before validating scope or decision, including final HR decisions.
  String table=kind.equals("OT")?"overtime_requests":"attendance_portal_requests",key=kind.equals("OT")?"overtime_id":"request_id";if(!Set.of("OT","ATTENDANCE").contains(kind))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Loại đơn không hợp lệ");
  db.queryForObject("SELECT "+key+" FROM dbo."+table+" WITH(UPDLOCK,HOLDLOCK) WHERE "+key+"=?",Long.class,id);
  var row=source(kind,id);if(!Objects.equals(expectedVersion,row.get("fingerprint")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Nội dung đơn đã thay đổi; tải lại trước khi quyết định");long employee=((Number)row.get("employee_id")).longValue();access.employee(p,employee,((java.sql.Timestamp)row.get("starts")).toLocalDateTime().toLocalDate(),true);
  if(!Set.of("CHO_DUYET","CHO_XU_LY","DANG_XU_LY").contains(row.get("sourceStatus")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Đơn đã hoàn tất xử lý cuối");
  if(db.queryForObject("SELECT COUNT_BIG(*) FROM dbo.department_workflow_reviews WITH(UPDLOCK,HOLDLOCK) WHERE source_type=? AND source_id=? AND source_fingerprint=?",Long.class,kind,id,row.get("fingerprint"))>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Đơn đã có quyết định cấp phòng cho phiên bản này");
  db.update("INSERT dbo.department_workflow_reviews(source_type,source_id,employee_id,reviewer_id,decision,reason,source_fingerprint) VALUES(?,?,?,?,?,?,?)",kind,id,employee,p.accountId(),approve?"APPROVED":"REJECTED",reason.trim(),row.get("fingerprint"));
  db.update("INSERT dbo.audit_logs(actor_account_id,action,target_table,target_record_key,reason) VALUES(?,?,'department_workflow_reviews',?,?)",p.accountId(),approve?"DEPARTMENT_APPROVE":"DEPARTMENT_REJECT",kind+":"+id,reason.trim());
  db.update("INSERT dbo.audit_logs(actor_account_id,action,target_table,target_record_key,reason) VALUES(?,?,?,?,?)",p.accountId(),approve?"DEPARTMENT_APPROVE":"DEPARTMENT_REJECT",kind.equals("OT")?"overtime_requests":"attendance_portal_requests",Long.toString(id),"Ý kiến cấp phòng: "+reason.trim());
  var recipients=db.queryForList("SELECT a.account_id FROM dbo.accounts a WHERE a.employee_id=? AND a.is_active=1",Long.class,employee);
  recipients=new ArrayList<>(recipients);LocalDate workDate=((java.sql.Timestamp)row.get("starts")).toLocalDateTime().toLocalDate();
  recipients.addAll(db.queryForList("SELECT ac.account_id FROM dbo.accounts ac JOIN dbo.roles role ON role.role_id=ac.role_id WHERE ac.is_active=1 AND (role.role_code='ADMIN' OR role.role_code='HR' AND EXISTS(SELECT 1 FROM dbo.hr_department_scopes scope JOIN dbo.employee_assignments member ON member.department_id=scope.department_id WHERE scope.hr_account_id=ac.account_id AND scope.revoked_at IS NULL AND scope.effective_from<=SYSUTCDATETIME() AND (scope.effective_to IS NULL OR scope.effective_to>SYSUTCDATETIME()) AND member.employee_id=? AND member.effective_from<=? AND (member.effective_to IS NULL OR member.effective_to>?)))",Long.class,employee,workDate,workDate));
  notices.enqueue("department:"+kind+":"+id+":"+row.get("fingerprint"),p.accountId(),"DEPARTMENT_REVIEW","Kết quả duyệt cấp phòng",approve?"Đơn của bạn đã được trưởng phòng đồng ý, chờ ADMIN/HR duyệt cuối.":"Trưởng phòng không đồng ý đề xuất. Mở chi tiết để xem lý do.","department_workflow_reviews",db.queryForObject("SELECT review_id FROM dbo.department_workflow_reviews WHERE source_type=? AND source_id=? AND source_fingerprint=?",Long.class,kind,id,row.get("fingerprint")),recipients);
 }
 @Transactional(value="scheduleTransactionManager",propagation=org.springframework.transaction.annotation.Propagation.MANDATORY)
 public void submittedOvertime(long id,long actor){
  if(!notices.enabled())return;var row=source("OT",id);long employee=((Number)row.get("employee_id")).longValue();LocalDate date=((java.sql.Timestamp)row.get("starts")).toLocalDateTime().toLocalDate();
  var heads=db.queryForList("SELECT DISTINCT ac.account_id FROM dbo.employee_assignments member JOIN dbo.employee_assignments head ON head.department_id=member.department_id JOIN dbo.positions pos ON pos.position_id=head.position_id AND pos.position_code='TRUONG_PHONG' JOIN dbo.accounts ac ON ac.employee_id=head.employee_id AND ac.is_active=1 JOIN dbo.employees leader ON leader.employee_id=head.employee_id AND leader.employment_status='DANG_LAM' WHERE member.employee_id=? AND member.effective_from<=? AND (member.effective_to IS NULL OR member.effective_to>?) AND head.effective_from<=? AND (head.effective_to IS NULL OR head.effective_to>?) AND head.employee_id<>?",Long.class,employee,date,date,access.today(),access.today(),employee);
  notices.enqueue("head-ot:"+id+":"+row.get("fingerprint"),actor,"HEAD_OT_SUBMITTED","Đơn tăng ca chờ duyệt cấp phòng","Có đơn tăng ca của nhân viên trong phòng đang chờ bạn xem xét.","department_ot_requests",id,heads);
 }
 public void requireApproval(String kind,long id){var row=source(kind,id);long employee=((Number)row.get("employee_id")).longValue();LocalDate date=((java.sql.Timestamp)row.get("starts")).toLocalDateTime().toLocalDate();
  Long privileged=db.queryForObject("SELECT COUNT_BIG(*) FROM dbo.accounts a JOIN dbo.roles role ON role.role_id=a.role_id WHERE a.employee_id=? AND a.is_active=1 AND role.role_code IN ('ADMIN','HR')",Long.class,employee);if(privileged!=null&&privileged>0)return;
  Long heads=db.queryForObject("SELECT COUNT_BIG(*) FROM dbo.employee_assignments member JOIN dbo.employee_assignments head ON head.department_id=member.department_id JOIN dbo.positions pos ON pos.position_id=head.position_id AND pos.position_code='TRUONG_PHONG' JOIN dbo.employees leader ON leader.employee_id=head.employee_id AND leader.employment_status='DANG_LAM' WHERE member.employee_id=? AND member.effective_from<=? AND (member.effective_to IS NULL OR member.effective_to>?) AND head.effective_from<=? AND (head.effective_to IS NULL OR head.effective_to>?) AND head.employee_id<>?",Long.class,employee,date,date,access.today(),access.today(),employee);
  if(heads==null||heads==0)return;
  Long approved=db.queryForObject("SELECT COUNT_BIG(*) FROM dbo.department_workflow_reviews WHERE source_type=? AND source_id=? AND source_fingerprint=? AND decision='APPROVED'",Long.class,kind,id,row.get("fingerprint"));if(approved==null||approved==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Cần trưởng phòng duyệt cấp phòng trước khi phê duyệt cuối");
 }
 public Map<String,Object> notification(long reviewId,java.security.Principal principal,PersonnelAccessService personnel){var actor=personnel.actor(principal);var review=db.queryForMap("SELECT * FROM dbo.department_workflow_reviews WHERE review_id=?",reviewId);long employee=((Number)review.get("employee_id")).longValue();if(actor.employeeId()!=employee){var scope=new PersonnelScopeService(db);if("EMPLOYEE".equals(actor.role()))access.employee(new AuthenticatedAccount(actor.accountId(),actor.employeeId(),principal.getName(),actor.role()),employee,access.today(),false);else{personnel.manager(principal);scope.employee(employee,true);}}var result=new LinkedHashMap<String,Object>(review);result.put("requestCode",source(review.get("source_type").toString(),((Number)review.get("source_id")).longValue()).get("code"));result.put("status",review.get("decision"));return result;}
}
